// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    uint256 initialBalance;

    function setUp() public {
        vm.deal(address(this), 1 ether);
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
        initialBalance = address(c).balance;
    }

    function testFuzz_property(uint96 value) public {
        vm.assume(value <= 100 ether);
        bytes32 hash = keccak256(abi.encodePacked(value));

        address caller = address(0xBEEF);
        vm.deal(caller, value);

        uint256 successCount = 0;

        vm.prank(caller);
        try c.lockInGuess{value: value}(hash) {
            successCount = 1;
        } catch {
        }

        uint256 expectedBalance = initialBalance + successCount * 1 ether;
        assertTrue(address(c).balance == expectedBalance);
    }
}
